/**
 * Python `bytes` emulation.
 *
 * A "bytes object" here is a plain JavaScript array of integers in [0, 255].
 * Plain arrays keep this layer free of any binary-view machinery: everything
 * below is ordinary arithmetic and string building.
 */

const BACKSLASH = 0x5c;
const QUOTE_SINGLE = 0x27;
const QUOTE_DOUBLE = 0x22;

/** Two lowercase hex digits, the way Python renders `\xHH`. */
function hex2(byte) {
  return byte.toString(16).padStart(2, '0');
}

/**
 * Encode a JavaScript string to UTF-8 bytes, mirroring `str.encode()`.
 * Iterating with `for...of` walks code points, so surrogate pairs collapse
 * into a single 4-byte sequence exactly as CPython does.
 */
export function encodeUtf8(text) {
  const out = [];
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/**
 * Render a bytes object the way `repr()` / `print()` does.
 *
 * Python prefers single quotes, but switches to double quotes when the data
 * contains a single quote and no double quote; when both appear it keeps
 * single quotes and backslash-escapes the embedded ones.
 */
export function reprBytes(bytes) {
  const hasSingle = bytes.includes(QUOTE_SINGLE);
  const hasDouble = bytes.includes(QUOTE_DOUBLE);
  const quote = hasSingle && !hasDouble ? QUOTE_DOUBLE : QUOTE_SINGLE;
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) {
      body += '\\' + String.fromCharCode(byte);
    } else if (byte === 0x09) {
      body += '\\t';
    } else if (byte === 0x0a) {
      body += '\\n';
    } else if (byte === 0x0d) {
      body += '\\r';
    } else if (byte >= 0x20 && byte < 0x7f) {
      body += String.fromCharCode(byte);
    } else {
      body += '\\x' + hex2(byte);
    }
  }
  return `b${quoteChar}${body}${quoteChar}`;
}

