/**
 * Python `str` helpers: code-point length and `repr()`.
 */

/** Unicode code points Python's `str.strip()` treats as whitespace. */
const WHITESPACE =
  '\t\n\v\f\r   ' +
  '           ' +
  '    　';

/**
 * `len(s)` counts code points, not UTF-16 units, so an astral character such
 * as an emoji contributes 1 here where `s.length` would report 2.
 */
export function codePointLength(text) {
  let count = 0;
  for (const _ of text) count += 1;
  return count;
}

/** `str.strip()` with no argument. */
export function pyStrip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && WHITESPACE.includes(text[start])) start += 1;
  while (end > start && WHITESPACE.includes(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * `repr()` of a string, used by argparse when it echoes a bad value back.
 * Quote selection follows the same rule as bytes: prefer `'`, switch to `"`
 * only when the text contains `'` but no `"`.
 */
export function reprStr(text) {
  const hasSingle = text.includes("'");
  const hasDouble = text.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let body = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') {
      body += '\\' + ch;
    } else if (ch === '\t') {
      body += '\\t';
    } else if (ch === '\n') {
      body += '\\n';
    } else if (ch === '\r') {
      body += '\\r';
    } else if (cp < 0x20 || cp === 0x7f) {
      body += escapeCodePoint(cp);
    } else {
      body += ch;
    }
  }
  return `${quote}${body}${quote}`;
}

