/**
 * Python `int(str)` semantics.
 *
 * Values are returned as BigInt so that huge literals survive intact — the
 * original script happily accepts `999999999999999999999` at parse time and
 * only rejects it later, when a fixed-width field tries to build it.
 */

import { pyStrip } from './str.mjs';

/** Raised for input `int()` would reject, mirroring Python's ValueError. */
export class ValueError extends Error {}

/**
 * Digits may be separated by single underscores (`1_000`), but an underscore
 * may not lead, trail, or double up. Anything else — `0x10`, `3.0`, `''` — is
 * a ValueError, just as in CPython.
 */
export function pyInt(text) {
  const stripped = pyStrip(text);
  const match = /^([+-]?)(\d(?:_?\d)*)$/.exec(stripped);
  if (match === null) {
    throw new ValueError(`invalid literal for int() with base 10: ${text}`);
  }
  const digits = match[2].replace(/_/g, '');
  const value = BigInt(digits);
  return match[1] === '-' ? -value : value;
}

