/**
 * A focused re-implementation of `argparse.ArgumentParser` covering the
 * behaviours this CLI exposes: long options with values, `=`-joined forms,
 * unambiguous prefix abbreviation, `--` termination, required-argument and
 * type-conversion diagnostics, and `-h/--help`.
 */

import { basename } from 'node:path';
import { reprStr } from '../python/str.mjs';
import { ValueError } from '../python/int.mjs';
import { formatHelp, formatUsage, terminalWidth } from './formatter.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Thrown internally so `parseArgs` can render usage before exiting with 2. */
class ArgumentError extends Error {}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog ?? basename(process.argv[1] ?? 'prog');
    this.actions = [];
    this.optionStringActions = new Map();
    this.#register({
      optionStrings: ['-h', '--help'],
      dest: 'help',
      takesValue: false,
      required: false,
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  #register(action) {
    this.actions.push(action);
    for (const optionString of action.optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /** Mirrors `parser.add_argument('--x', type=..., required=...)`. */
  addArgument(optionString, { type = String, required = false, help = null } = {}) {
    const dest = optionString.replace(/^-+/, '').replace(/-/g, '_');
    return this.#register({
      optionStrings: [optionString],
      dest,
      takesValue: true,
      metavar: dest.toUpperCase(),
      type,
      required,
      isHelp: false,
      help,
    });
  }

  get #width() {
    return terminalWidth();
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions, this.#width) + '\n';
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions, this.#width);
  }

  /** `parser.error()`: usage on stderr, message, exit status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /**
   * Decide whether a token is an option. Returns `null` when the token should
   * be treated as a value, otherwise a descriptor whose `action` is `null` for
   * an unrecognised option.
   */
  #classify(token) {
    if (token.length === 0) return null;
    if (!token.startsWith('-')) return null;
    if (this.optionStringActions.has(token)) {
      return { action: this.optionStringActions.get(token), optionString: token, explicit: null };
    }
    if (token.length === 1) return null;

    if (token.includes('=')) {
      const eq = token.indexOf('=');
      const head = token.slice(0, eq);
      if (this.optionStringActions.has(head)) {
        return {
          action: this.optionStringActions.get(head),
          optionString: head,
          explicit: token.slice(eq + 1),
        };
      }
    }

    const matches = this.#optionTuples(token);
    if (matches.length > 1) {
      const names = matches.map((m) => m.optionString).join(', ');
      throw new ArgumentError(`ambiguous option: ${token} could match ${names}`);
    }
    if (matches.length === 1) return matches[0];

    // No option matched: negative numbers and anything containing a space are
    // values, since no option string here looks like a negative number.
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicit: null };
  }

  /** Prefix-abbreviation lookup, `_get_option_tuples` in argparse. */
  #optionTuples(token) {
    const results = [];
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const prefix = eq === -1 ? token : token.slice(0, eq);
      const explicit = eq === -1 ? null : token.slice(eq + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) results.push({ action, optionString, explicit });
      }
      return results;
    }
    const shortPrefix = token.slice(0, 2);
    const shortExplicit = token.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        results.push({ action, optionString, explicit: shortExplicit });
      } else if (optionString.startsWith(token)) {
        results.push({ action, optionString, explicit: null });
      }
    }
    return results;
  }

  /** `'/'.join(action.option_strings)`, used to label error messages. */
  #actionName(action) {
    return action.optionStrings.join('/');
  }

  #convert(action, raw) {
    if (action.type === String) return raw;
    try {
      return action.type(raw);
    } catch (err) {
      if (err instanceof ValueError) {
        const typeName = action.type.pyName ?? action.type.name;
        throw new ArgumentError(
          `argument ${this.#actionName(action)}: invalid ${typeName} value: ${reprStr(raw)}`,
        );
      }
      throw err;
    }
  }

  parseArgs(argv = process.argv.slice(2)) {
    try {
      return this.#parse(argv);
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }
  }

  #parse(argv) {
    const namespace = Object.create(null);
    const seen = new Set();
    const extras = [];
    let terminated = false;

    for (let index = 0; index < argv.length; index += 1) {
      const token = argv[index];

      if (terminated) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        terminated = true;
        continue;
      }

      const option = this.#classify(token);
      if (option === null) {
        extras.push(token);
        continue;
      }
      if (option.action === null) {
        extras.push(token);
        continue;
      }

      const { action, explicit } = option;

      if (action.isHelp) {
        if (explicit !== null) {
          throw new ArgumentError(
            `argument ${this.#actionName(action)}: ignored explicit argument ${reprStr(explicit)}`,
          );
        }
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      let raw = explicit;
      if (raw === null) {
        const next = index + 1 < argv.length ? argv[index + 1] : null;
        // A `--` barrier or another option cannot serve as this option's value.
        if (next === null || next === '--' || this.#classify(next) !== null) {
          throw new ArgumentError(`argument ${this.#actionName(action)}: expected one argument`);
        }
        raw = next;
        index += 1;
      }

      namespace[action.dest] = this.#convert(action, raw);
      seen.add(action);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => this.#actionName(action));
    if (missing.length > 0) {
      throw new ArgumentError(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      throw new ArgumentError(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

