/**
 * Exception types mirroring `construct.core`.
 *
 * Each error carries the Python frames the real library would have pushed onto
 * the traceback, plus an optional chained `struct.error` for the
 * "During handling of the above exception" section.
 */

export class ConstructError extends Error {
  /**
   * @param {string} pyType     dotted Python class name, e.g. `construct.core.StreamError`
   * @param {string} pyMessage  the exception text, newlines included
   * @param {object} options    `libFrames` and an optional chained `cause`
   */
  constructor(pyType, pyMessage, { libFrames = [], cause = null } = {}) {
    super(pyMessage);
    this.pyType = pyType;
    this.pyMessage = pyMessage;
    this.libFrames = libFrames;
    this.pyCause = cause;
  }
}

export class FormatFieldError extends ConstructError {
  constructor(pyMessage, options) {
    super('construct.core.FormatFieldError', pyMessage, options);
  }
}

export class StreamError extends ConstructError {
  constructor(pyMessage, options) {
    super('construct.core.StreamError', pyMessage, options);
  }
}

/** A single `File "...", line N, in name` traceback entry. */
export function frame(file, line, func) {
  return { file, line, func };
}

