/**
 * Fixed-width integer fields (`construct.FormatField`).
 *
 * Values arrive as BigInt so out-of-range checks stay exact for literals far
 * beyond Number.MAX_SAFE_INTEGER, which the underlying `struct` module rejects
 * by value rather than truncating.
 */

import { FormatFieldError, frame } from './errors.mjs';

/** Frames `struct.pack` failures produce inside construct. */
const BUILD_FRAMES = [
  frame('construct/core.py', 452, 'build'),
  frame('construct/core.py', 464, 'build_stream'),
  frame('construct/core.py', 1167, '_build'),
];
const STRUCT_FRAMES = [frame('construct/core.py', 1165, '_build')];

class FormatField {
  /**
   * @param {string} fmt   the `struct` format string, e.g. `'<B'`
   * @param {string} code  the format character used in `struct` diagnostics
   * @param {number} size  width in bytes
   */
  constructor(fmt, code, size) {
    this.fmt = fmt;
    this.code = code;
    this.size = size;
    this.max = (1n << BigInt(size * 8)) - 1n;
  }

  /** Little-endian unsigned packing, returned as an array of byte values. */
  build(value) {
    const number = BigInt(value);
    if (number < 0n || number > this.max) {
      throw new FormatFieldError(
        `Error in path (building)\nstruct '${this.fmt}' error during building, given value ${number}`,
        {
          libFrames: BUILD_FRAMES,
          cause: {
            type: 'struct.error',
            message: `'${this.code}' format requires 0 <= number <= ${this.max}`,
            frames: STRUCT_FRAMES,
          },
        },
      );
    }

    const bytes = [];
    let rest = number;
    for (let i = 0; i < this.size; i += 1) {
      bytes.push(Number(rest & 0xffn));
      rest >>= 8n;
    }
    return bytes;
  }
}

export const Int8ul = new FormatField('<B', 'B', 1);
export const Int16ul = new FormatField('<H', 'H', 2);
export const Int32ul = new FormatField('<L', 'L', 4);
export const Int64ul = new FormatField('<Q', 'Q', 8);

