/**
 * Fixed-length raw byte fields (`construct.Bytes`).
 */

import { StreamError, frame } from './errors.mjs';

const BUILD_FRAMES = [
  frame('construct/core.py', 452, 'build'),
  frame('construct/core.py', 464, 'build_stream'),
  frame('construct/core.py', 970, '_build'),
  frame('construct/core.py', 195, 'stream_write'),
];

class BytesField {
  constructor(length) {
    this.length = length;
  }

  /**
   * The payload is written verbatim, but its length must match the declared
   * size exactly — a short or long buffer fails at the stream layer.
   */
  build(data) {
    if (data.length !== this.length) {
      throw new StreamError(
        `Error in path (building)\nbytes object of wrong length, expected ${this.length}, found ${data.length}`,
        { libFrames: BUILD_FRAMES },
      );
    }
    return data.slice();
  }
}

export function Bytes(length) {
  return new BytesField(length);
}

