  const result6 = at(23, () => construct.Int8ul.build(args.g));
  const result7 = at(24, () => construct.Int8ul.build(args.i));
  const result8 = at(25, () =>
    construct.Bytes(codePointLength(args.h)).build(encodeUtf8(args.h)),
  );
  const result9 = at(26, () =>
    construct.Int8ul.build(pyMod(args.a + args.b + args.c, 256n)),
  );

