/**
 * Usage / help rendering, ported from argparse's HelpFormatter.
 *
 * Only the pieces this CLI can reach are implemented: a prog line, a flat list
 * of optionals, and the automatic `-h/--help` entry. The line-breaking rules
 * are reproduced faithfully so wrapped usage lines land on the same columns.
 */

const MAX_HELP_POSITION = 24;
const DEFAULT_COLUMNS = 80;

/**
 * argparse sizes its output from `shutil.get_terminal_size()`, which consults
 * COLUMNS first and falls back to 80 when the stream is not a terminal.
 */
export function terminalWidth() {
  const env = process.env.COLUMNS;
  if (env !== undefined && /^\s*[+-]?\d+\s*$/.test(env)) {
    const columns = Number.parseInt(env, 10);
    if (columns > 0) return columns - 2;
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns - 2;
  }
  return DEFAULT_COLUMNS - 2;
}

/** `[-h]` for optional flags, `--a A` for required ones taking a value. */
export function formatActionInvocation(action) {
  const primary = action.optionStrings[0];
  if (action.takesValue) return `${primary} ${action.metavar}`;
  return primary;
}

function formatUsagePart(action) {
  const text = formatActionInvocation(action);
  return action.required ? text : `[${text}]`;
}

/**
 * Greedy packing identical to argparse's inner `get_lines()`: parts are added
 * until the line would exceed the text width, and continuation lines are
 * aligned under the first part after `usage: <prog> `.
 */
function packLines(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLen = (prefix !== null ? prefix.length : indent.length) - 1;

  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** The `usage: ...` block, without a trailing newline. */
export function formatUsage(prog, actions, width) {
  const prefix = 'usage: ';
  const parts = actions.map(formatUsagePart);
  const oneLine = `${prog} ${parts.join(' ')}`.trimEnd();

  if (prefix.length + oneLine.length <= width) return prefix + oneLine;

  if (prefix.length + prog.length <= 0.75 * width) {
    const indent = ' '.repeat(prefix.length + prog.length + 1);
    return prefix + packLines([prog, ...parts], indent, width, prefix).join('\n');
  }
  const indent = ' '.repeat(prefix.length);
  return prefix + [prog, ...packLines(parts, indent, width, null)].join('\n');
}

/** Wrap help text to the column reserved for descriptions. */
function wrapHelp(text, width) {
  const words = text.split(/\s+/).filter((word) => word.length > 0);
  const lines = [];
  let line = '';
  for (const word of words) {
    if (line === '') {
      line = word;
    } else if (line.length + 1 + word.length <= width) {
      line += ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }
  if (line !== '') lines.push(line);
  return lines.length > 0 ? lines : [''];
}

/** The full `--help` screen, terminated by a newline. */
export function formatHelp(prog, actions, width) {
  const indent = 2;
  let actionMaxLength = 0;
  for (const action of actions) {
    actionMaxLength = Math.max(actionMaxLength, formatActionInvocation(action).length + indent);
  }
  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
  const actionWidth = Math.max(helpPosition - indent - 2, 1);
  const helpWidth = Math.max(width - helpPosition, 11);

  let out = formatUsage(prog, actions, width) + '\n\n';
  out += 'options:\n';
  for (const action of actions) {
    const header = formatActionInvocation(action);
    if (!action.help) {
      out += ' '.repeat(indent) + header + '\n';
      continue;
    }
    const helpLines = wrapHelp(action.help, helpWidth);
    if (header.length <= actionWidth) {
      out += ' '.repeat(indent) + header.padEnd(actionWidth) + '  ' + helpLines[0] + '\n';
    } else {
      out += ' '.repeat(indent) + header + '\n';
      out += ' '.repeat(helpPosition) + helpLines[0] + '\n';
    }
    for (const extra of helpLines.slice(1)) {
      out += ' '.repeat(helpPosition) + extra + '\n';
    }
  }
  return out;
}

