/**
 * Renders CPython-style tracebacks for the errors raised by the construct
 * shim, including chained exceptions and the fine-grained caret anchors
 * Python 3.11+ prints beneath the failing expression.
 *
 * Source lines are looked up the way `linecache` does — by opening the
 * recorded filename relative to the current directory. When the file is not
 * there the frame prints as a bare `File "...", line N, in name`, exactly as
 * the frozen executable does when run from outside the script's directory.
 */

import { readFileSync } from 'node:fs';

const lineCache = new Map();

/** `linecache.getline()`: the requested 1-based line, or null if unavailable. */
function getLine(file, lineno) {
  if (!lineCache.has(file)) {
    let lines = null;
    try {
      lines = readFileSync(file, 'utf8').split('\n');
    } catch {
      lines = null;
    }
    lineCache.set(file, lines);
  }
  const lines = lineCache.get(file);
  if (lines === null || lineno < 1 || lineno > lines.length) return null;
  return lines[lineno - 1].replace(/\r$/, '');
}

/**
 * Build a script frame.
 *
 * `colOffset` / `endColOffset` are the compiled column bounds of the
 * sub-expression that raised; they drive the caret anchors and are applied to
 * whatever source line is found, since that is what CPython does.
 */
export function scriptFrame(file, line, func, colOffset = null, endColOffset = null) {
  return { file, line, func, colOffset, endColOffset };
}

function formatScriptFrame({ file, line, func, colOffset, endColOffset }) {
  let out = `  File "${file}", line ${line}, in ${func}\n`;

  const raw = getLine(file, line);
  if (raw === null) return out;
  const stripped = raw.trim();
  if (stripped === '') return out;
  out += `    ${stripped}\n`;

  if (colOffset === null || endColOffset === null) return out;

  const strippedChars = raw.length - raw.trimStart().length;
  const width = endColOffset - colOffset;
  const indent = colOffset - strippedChars;
  // Carets are suppressed when the anchor already spans the whole line.
  if (width < stripped.length && width > 0 && indent >= 0) {
    out += `    ${' '.repeat(indent)}${'^'.repeat(width)}\n`;
  }
  return out;
}

function formatLibFrame({ file, line, func }) {
  return `  File "${file}", line ${line}, in ${func}\n`;
}

/**
 * @param {import('./construct/errors.mjs').ConstructError} error
 * @param {Array} scriptFrames outermost first
 */
export function renderTraceback(error, scriptFrames) {
  let out = '';

  if (error.pyCause) {
    out += 'Traceback (most recent call last):\n';
    out += error.pyCause.frames.map(formatLibFrame).join('');
    out += `${error.pyCause.type}: ${error.pyCause.message}\n`;
    out += '\nDuring handling of the above exception, another exception occurred:\n\n';
  }

  out += 'Traceback (most recent call last):\n';
  out += scriptFrames.map(formatScriptFrame).join('');
  out += error.libFrames.map(formatLibFrame).join('');
  out += `${error.pyType}: ${error.pyMessage}\n`;
  return out;
}

/**
 * The frozen-executable footer. The bracketed number is the process id, which
 * is why it differs between runs of the original binary too.
 */
export function frozenFooter(scriptName) {
  return `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`;
}

