#!/usr/bin/env node
/**
 * Node.js port of test19.py.
 *
 * Builds a handful of little-endian integer fields and two raw byte blobs with
 * the `construct` shim, then prints each result using Python's `bytes` repr.
 */

import { ArgumentParser } from './lib/argparse/index.mjs';
import * as construct from './lib/construct/index.mjs';
import { ConstructError } from './lib/construct/errors.mjs';
import { pyInt } from './lib/python/int.mjs';
import { encodeUtf8, reprBytes } from './lib/python/bytes.mjs';
import { codePointLength } from './lib/python/str.mjs';
import { frozenFooter, renderTraceback, scriptFrame } from './lib/pytraceback.mjs';

const SCRIPT_FILE = 'test19.py';
const SCRIPT_NAME = 'test19';

/**
 * Source text of the build statements, keyed by line number in test19.py.
 * A traceback quotes the failing line verbatim, so the text is kept here
 * rather than reconstructed.
 */
const SOURCE_LINES = {
  18: '    result1 = construct.Int8ul.build(args.a)  # 构建第一个字段',
  19: '    result2 = construct.Int16ul.build(args.b)  # 构建第二个字段',
  20: '    result3 = construct.Int8ul.build(args.c)  # 构建第三个字段',
  21: '    result4 = construct.Bytes(len(args.d)).build(args.d.encode())  # 构建字符串数据，使用实际长度',
  22: '    result5 = construct.Int8ul.build(args.f)  # 构建第五个字段',
  23: '    result6 = construct.Int8ul.build(args.g)  # 构建第六个字段',
  24: '    result7 = construct.Int8ul.build(args.i)  # 构建第七个字段',
  25: '    result8 = construct.Bytes(len(args.h)).build(args.h.encode())  # 构建第二个字符串数据，使用实际长度',
  26: '    result9 = construct.Int8ul.build((args.a + args.b + args.c) % 256)  # 构建校验字段，确保在字节范围内',
};

/** Tag a build step with its source line so failures produce a real traceback. */
function at(line, build) {
  try {
    return build();
  } catch (err) {
    if (err instanceof ConstructError) err.pyLine = line;
    throw err;
  }
}

/** `print(x)` for a bytes object. */
function print(bytes) {
  process.stdout.write(reprBytes(bytes) + '\n');
}

/** Python's `%` is floor modulo, so the result is never negative. */
function pyMod(value, modulus) {
  return ((value % modulus) + modulus) % modulus;
}

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: pyInt, required: true });
  parser.addArgument('--b', { type: pyInt, required: true });
  parser.addArgument('--c', { type: pyInt, required: true });
  parser.addArgument('--d', { type: String, required: true });
  parser.addArgument('--e', { type: pyInt, required: true });
  parser.addArgument('--f', { type: pyInt, required: true });
  parser.addArgument('--g', { type: pyInt, required: true });
  parser.addArgument('--h', { type: String, required: true });
