#!/usr/bin/env node
/**
 * Node.js port of test19.py.
 *
 * Builds a handful of little-endian integer fields and two raw byte blobs with
 * the `construct` shim, then prints each result using Python's `bytes` repr.
 */

import { ArgumentParser } from './lib/argparse/index.mjs';
import * as construct from './lib/construct/index.mjs';
import { ConstructError } from './lib/construct/errors.mjs';
import { pyInt } from './lib/python/int.mjs';
import { encodeUtf8, reprBytes } from './lib/python/bytes.mjs';
import { codePointLength } from './lib/python/str.mjs';
import { frozenFooter, renderTraceback, scriptFrame } from './lib/pytraceback.mjs';

const SCRIPT_FILE = 'test19.py';
const SCRIPT_NAME = 'test19';

/**
 * Column bounds of the `construct...` call on each build line of test19.py,
 * used to place the traceback caret anchors. `main()` on line 38 spans its
 * whole line, so Python prints no carets for it.
 */
const ANCHORS = {
  18: [14, 44],
  19: [14, 45],
  20: [14, 44],
  21: [14, 65],
  22: [14, 44],
  23: [14, 44],
  24: [14, 44],
  25: [14, 65],
  26: [14, 70],
};

/** Tag a build step with its source line so failures produce a real traceback. */
function at(line, build) {
  try {
    return build();
  } catch (err) {
    if (err instanceof ConstructError) err.pyLine = line;
    throw err;
  }
}

/** `print(x)` for a bytes object. */
function print(bytes) {
  process.stdout.write(reprBytes(bytes) + '\n');
}

/** Python's `%` is floor modulo, so the result is never negative. */
function pyMod(value, modulus) {
  return ((value % modulus) + modulus) % modulus;
}

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: pyInt, required: true });
  parser.addArgument('--b', { type: pyInt, required: true });
  parser.addArgument('--c', { type: pyInt, required: true });
  parser.addArgument('--d', { type: String, required: true });
  parser.addArgument('--e', { type: pyInt, required: true });
  parser.addArgument('--f', { type: pyInt, required: true });
  parser.addArgument('--g', { type: pyInt, required: true });
  parser.addArgument('--h', { type: String, required: true });
  parser.addArgument('--i', { type: pyInt, required: true });
  const args = parser.parseArgs();

  const result1 = at(18, () => construct.Int8ul.build(args.a));
  const result2 = at(19, () => construct.Int16ul.build(args.b));
  const result3 = at(20, () => construct.Int8ul.build(args.c));
  const result4 = at(21, () =>
    construct.Bytes(codePointLength(args.d)).build(encodeUtf8(args.d)),
  );
  const result5 = at(22, () => construct.Int8ul.build(args.f));
  const result6 = at(23, () => construct.Int8ul.build(args.g));
  const result7 = at(24, () => construct.Int8ul.build(args.i));
  const result8 = at(25, () =>
    construct.Bytes(codePointLength(args.h)).build(encodeUtf8(args.h)),
  );
  const result9 = at(26, () =>
    construct.Int8ul.build(pyMod(args.a + args.b + args.c, 256n)),
  );

  print(result1);
  print(result2);
  print(result3);
  print(result4);
  print(result5);
  print(result6);
  print(result7);
  print(result8);
  print(result9);
}

try {
  main();
} catch (err) {
  if (!(err instanceof ConstructError)) throw err;
  const frames = [
    scriptFrame(SCRIPT_FILE, 38, '<module>', '    main()'),
    scriptFrame(SCRIPT_FILE, err.pyLine, 'main', SOURCE_LINES[err.pyLine], { anchor: true }),
  ];
  process.stderr.write(renderTraceback(err, frames));
  process.stderr.write(frozenFooter(SCRIPT_NAME));
  process.exit(1);
}

